// Synthesised catalogue — flat list of canonical FACIS data products.
// Each entry mirrors the columns the gold-layer `data_products` table is
// expected to expose. Replace with a Trino query once the table exists.
const now = new Date().toISOString();
const CATALOGUE = [
    { id: 'dp-energy-meter-readings',  domain: 'energy', name: 'Smart Meter Readings',     version: '2.1.0', semanticScope: 'energy.metering.harmonised.v2', sourceFeed: 'latest_meters',    apiStatus: 'available', lastUpdated: now, description: 'Harmonised AMR meter readings across all managed sites.' },
    { id: 'dp-energy-pv-output',       domain: 'energy', name: 'PV System Output',         version: '1.4.0', semanticScope: 'energy.generation.pv.v1',     sourceFeed: 'latest_pv',        apiStatus: 'available', lastUpdated: now, description: 'Per-system PV generation, irradiance, and inverter status.' },
    { id: 'dp-energy-loads',           domain: 'energy', name: 'Consumer Loads',           version: '1.2.0', semanticScope: 'energy.loads.v1',             sourceFeed: 'latest_consumers', apiStatus: 'available', lastUpdated: now, description: 'Aggregated consumer device load profiles.' },
    { id: 'dp-city-lighting',          domain: 'city',   name: 'Smart Lighting Status',    version: '1.0.1', semanticScope: 'city.lighting.dali.v1',       sourceFeed: 'streetlights',     apiStatus: 'available', lastUpdated: now, description: 'Per-zone aggregated streetlight dimming + power telemetry.' },
    { id: 'dp-city-traffic',           domain: 'city',   name: 'Traffic Zone Index',       version: '1.0.0', semanticScope: 'city.traffic.zone-index.v1',  sourceFeed: 'traffic',          apiStatus: 'available', lastUpdated: now, description: 'Per-zone traffic index normalised 0..1.' },
    { id: 'dp-city-events',            domain: 'city',   name: 'City Events Stream',       version: '1.0.0', semanticScope: 'city.events.v1',              sourceFeed: 'events',           apiStatus: 'available', lastUpdated: now, description: 'Active and recent city-level events keyed by zone.' },
    { id: 'dp-city-weather',           domain: 'city',   name: 'City Weather Snapshot',    version: '1.0.0', semanticScope: 'city.weather.fog-visibility.v1','sourceFeed': 'city-weather',  apiStatus: 'available', lastUpdated: now, description: 'Fog index, visibility, sunrise/sunset for the operational area.' }
];

const action = msg._req && msg._req.action;
const payload = (msg._req && msg._req.payload) || {};

if (action === 'data-products.list') {
    msg._result = { ok: true, data: { products: CATALOGUE, count: CATALOGUE.length } };
    return msg;
}
if (action === 'data-products.energy.list') {
    const products = CATALOGUE.filter(p => p.domain === 'energy');
    msg._result = { ok: true, data: { products, count: products.length } };
    return msg;
}
if (action === 'data-products.city.list') {
    const products = CATALOGUE.filter(p => p.domain === 'city');
    msg._result = { ok: true, data: { products, count: products.length } };
    return msg;
}
if (action === 'data-products.detail') {
    const id = payload.id;
    if (!id) {
        msg._result = { ok: false, errors: { fields: { id: 'required' } } };
        return msg;
    }
    const found = CATALOGUE.find(p => p.id === id);
    if (!found) {
        msg._result = { ok: false, errors: { action: 'product not found' } };
        return msg;
    }
    msg._result = { ok: true, data: { product: found } };
    return msg;
}

msg._result = { ok: false, errors: { action: 'data-products: unknown action: ' + action } };
return msg;
